import{_ as e,c as o,a2 as t,o as r}from"./chunks/framework.DpbDeoNR.js";const s="/pub-blog/assets/image-20251221211420491.B2adGlpr.png",i="/pub-blog/assets/image-20251221211738225.DIbrTxi3.png",p="/pub-blog/assets/image-20251221212416142.Bk_c_2bR.png",n="/pub-blog/assets/image-20251221212502217.DiG9VHq5.png",c="/pub-blog/assets/image-20251221212707611.4iwKlD19.png",l="/pub-blog/assets/image-20251221212813537.iUQ-Ct12.png",d="/pub-blog/assets/image-20251221212838563.z-1GpHEL.png",m="/pub-blog/assets/image-20251221212951496.Beg1Jo_u.png",b="/pub-blog/assets/image-20251221213721538.EdoHfv0M.png",H=JSON.parse('{"title":"HarmonyOS6 接入分享，原来也是三分钟的事情","description":"","frontmatter":{},"headers":[],"relativePath":"鸿蒙开发技巧/HarmonyOS6 接入分享，原来也是三分钟的事情/HarmonyOS6 接入分享，原来也是三分钟的事情.md","filePath":"鸿蒙开发技巧/HarmonyOS6 接入分享，原来也是三分钟的事情/HarmonyOS6 接入分享，原来也是三分钟的事情.md","lastUpdated":1766324469000}'),g={name:"鸿蒙开发技巧/HarmonyOS6 接入分享，原来也是三分钟的事情/HarmonyOS6 接入分享，原来也是三分钟的事情.md"};function h(_,a,u,f,k,q){return r(),o("div",null,a[0]||(a[0]=[t('<h1 id="harmonyos6-接入分享-原来也是三分钟的事情" tabindex="-1">HarmonyOS6 接入分享，原来也是三分钟的事情 <a class="header-anchor" href="#harmonyos6-接入分享-原来也是三分钟的事情" aria-label="Permalink to &quot;HarmonyOS6 接入分享，原来也是三分钟的事情&quot;">​</a></h1><h2 id="前言" tabindex="-1">前言 <a class="header-anchor" href="#前言" aria-label="Permalink to &quot;前言&quot;">​</a></h2><p>最近打算给准备开发的应用接入分享功能，考虑到模板市场上已经有现成的模版了，然后结合AI来接入，接入起来，也就是3分钟的事情。</p><h2 id="新建工程" tabindex="-1">新建工程 <a class="header-anchor" href="#新建工程" aria-label="Permalink to &quot;新建工程&quot;">​</a></h2><p>如果还没有工程的话，直接新建工程、创建项目</p><p><img src="'+s+'" alt="image-20251221211420491"></p><h2 id="组件市场直接接入" tabindex="-1">组件市场直接接入 <a class="header-anchor" href="#组件市场直接接入" aria-label="Permalink to &quot;组件市场直接接入&quot;">​</a></h2><p>在devEco Studio 上的 组件市场上搜索，<strong>通用系统分享</strong>，然后直接下载到项目中即可。</p><p><img src="'+i+'" alt="image-20251221211738225"></p><p>成功后，系统会自动同步和构建，这个时候会提示文件找不到 <strong>build-profile.json5</strong>，</p><p><img src="'+p+'" alt="image-20251221212416142"></p><p>这个时候手动删除配置即可</p><p><img src="'+n+'" alt="image-20251221212502217"></p><h2 id="ai工具直接帮你接入" tabindex="-1">AI工具直接帮你接入 <a class="header-anchor" href="#ai工具直接帮你接入" aria-label="Permalink to &quot;AI工具直接帮你接入&quot;">​</a></h2><p>然后使用自己习惯的AI编辑器打开当前工程，万少这边使用的是 <strong>Trae 海外版 + Gemini-3-pro 模型</strong></p><p><img src="'+c+'" alt="image-20251221212707611"></p><p>你点击刚才组件市场内的通用分享组件的官网链接，复制这个网址。</p><blockquote><p><a href="https://developer.huawei.com/consumer/cn/market/prod-detail/cbc8bb4edde94e9097f366233bf2cfd5/2adce9bbd4cb42d58a87e6add45594b3" target="_blank" rel="noreferrer">https://developer.huawei.com/consumer/cn/market/prod-detail/cbc8bb4edde94e9097f366233bf2cfd5/2adce9bbd4cb42d58a87e6add45594b3</a></p></blockquote><p><img src="'+l+'" alt="image-20251221212813537"></p><hr><p><img src="'+d+'" alt="image-20251221212838563"></p><p>最后，使用<strong>老奶奶</strong>也能听懂的自然语言帮你的AI编辑器帮你接入即可，如图所示。</p><p><img src="'+m+'" alt="image-20251221212951496"></p><h2 id="最后效果" tabindex="-1">最后效果 <a class="header-anchor" href="#最后效果" aria-label="Permalink to &quot;最后效果&quot;">​</a></h2><p><img src="'+b+'" alt="image-20251221213721538"></p><h2 id="注意事项" tabindex="-1">注意事项 <a class="header-anchor" href="#注意事项" aria-label="Permalink to &quot;注意事项&quot;">​</a></h2><ol><li>如果需要接受比如分享到QQ后到回调</li><li>或者需要配置微博分享</li></ol><p>都需要仔细查看组件官网的描述</p><blockquote><p><a href="https://developer.huawei.com/consumer/cn/market/prod-detail/cbc8bb4edde94e9097f366233bf2cfd5/2adce9bbd4cb42d58a87e6add45594b3" target="_blank" rel="noreferrer">https://developer.huawei.com/consumer/cn/market/prod-detail/cbc8bb4edde94e9097f366233bf2cfd5/2adce9bbd4cb42d58a87e6add45594b3</a></p></blockquote><h2 id="联系我" tabindex="-1">联系我 <a class="header-anchor" href="#联系我" aria-label="Permalink to &quot;联系我&quot;">​</a></h2><p>可以加我微信，带你了解更多互联网 HarmonyOS相关的资讯。</p><p><img src="https://wsy996.obs.cn-east-3.myhuaweicloud.com:443/%E5%BE%AE%E4%BF%A1%E5%8F%B7%E5%92%8C%E4%BA%8C%E7%BB%B4%E7%A0%81.jpg" alt=""></p>',32)]))}const S=e(g,[["render",h]]);export{H as __pageData,S as default};
